<?php
declare(strict_types=1);
require_once '../conexao.php';
require_once '../helpers/auth.php';
require_once '../helpers/seguranca.php';
require_once '../helpers/pedidos.php';
$admin=exigirLoginAdmin();

$tipo=$_GET['tipo']??'';
$where="p.status IN ('em_espera','aguardando_nova_analise')";
$params=[];
if($tipo==='nova') $where="p.status='aguardando_nova_analise'";
if($tipo==='espera') $where="p.status='em_espera'";
if($tipo==='antiga') $where="p.status='em_espera' AND p.espera_desde <= DATE_SUB(NOW(), INTERVAL 3 DAY)";

$sql="SELECT p.id,p.paciente_id,p.protocolo,p.status,p.motivo_espera,p.espera_desde,p.ultima_resposta_paciente,p.criado_em,paciente.nome AS paciente_nome,e.nome AS exame_nome,esp.nome AS especialidade_nome,
(SELECT COUNT(*) FROM documentos_exames d WHERE d.pedido_id=p.id) AS qtd_docs,
(SELECT COUNT(*) FROM notificacoes_admin n WHERE n.pedido_id=p.id AND n.lida=0) AS novas_notificacoes
FROM pedidos_exames p INNER JOIN pacientes paciente ON paciente.id=p.paciente_id INNER JOIN exames e ON e.id=p.exame_id INNER JOIN especialidades esp ON esp.id=e.especialidade_id WHERE $where ORDER BY (p.status='aguardando_nova_analise') DESC, p.espera_desde ASC, p.id ASC";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$pendencias=$stmt->fetchAll();
$novas=(int)$pdo->query("SELECT COUNT(*) FROM notificacoes_admin WHERE lida=0")->fetchColumn();
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central de Pendências</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../css/exames.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>body{background:#f4f6f8;padding:20px}.box{background:#fff;border:1px solid #dfe4ea;border-radius:12px;padding:18px}.pending-new{border-left:5px solid #0d6efd}.pending-old{border-left:5px solid #dc3545}.time{font-weight:700}</style></head><body><div class="container-fluid" style="max-width:1150px"><div class="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-2"><div><h2 class="fw-bold text-primary mb-1">Central de Pendências</h2><p class="text-muted mb-0">Acompanhe pedidos em espera e novas respostas dos pacientes.</p></div><div><a href="dashboard.php" class="btn btn-outline-primary btn-sm me-1">Dashboard</a><a href="listagem_ordens.php" class="btn btn-outline-secondary btn-sm">Pedidos</a></div></div>
<div class="row g-3 mb-4"><div class="col-md-4"><a class="text-decoration-none" href="?tipo=nova"><div class="box"><div class="text-primary fw-bold">Novas respostas</div><div class="display-6 fw-bold"><?=$novas?></div></div></a></div><div class="col-md-4"><a class="text-decoration-none" href="?tipo=espera"><div class="box"><div class="text-warning fw-bold">Em espera</div><div class="display-6 fw-bold"><?=(int)$pdo->query("SELECT COUNT(*) FROM pedidos_exames WHERE status='em_espera'")->fetchColumn()?></div></div></a></div><div class="col-md-4"><a class="text-decoration-none" href="?tipo=antiga"><div class="box"><div class="text-danger fw-bold">Em espera há mais de 3 dias</div><div class="display-6 fw-bold"><?=(int)$pdo->query("SELECT COUNT(*) FROM pedidos_exames WHERE status='em_espera' AND espera_desde <= DATE_SUB(NOW(), INTERVAL 3 DAY)")->fetchColumn()?></div></div></a></div></div>
<div class="box"><div class="d-flex justify-content-between mb-3"><h5 class="fw-bold mb-0">Pedidos que precisam de atenção</h5><a href="pendencias.php" class="btn btn-outline-secondary btn-sm">Todas</a></div><?php if(!$pendencias): ?><div class="alert alert-light border text-center">Nenhuma pendência encontrada.</div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Paciente</th><th>Pedido</th><th>Status</th><th>Tempo</th><th>Última resposta</th><th></th></tr></thead><tbody><?php foreach($pendencias as $p): ?><tr class="<?= $p['status']==='aguardando_nova_analise'?'pending-new':(($p['espera_desde'] && strtotime($p['espera_desde']) <= strtotime('-3 days'))?'pending-old':'') ?>"><td><strong><?=htmlspecialchars($p['paciente_nome'])?></strong><br><small class="text-muted"><?=htmlspecialchars($p['especialidade_nome'])?></small></td><td><?=htmlspecialchars($p['exame_nome'])?><br><small><?=htmlspecialchars($p['protocolo'])?></small></td><td><span class="badge-status st-<?=htmlspecialchars($p['status'])?>"><?=ucwords(str_replace('_',' ',$p['status']))?></span><?php if($p['novas_notificacoes']): ?><span class="badge bg-primary ms-1">NOVO</span><?php endif; ?></td><td><?php if($p['espera_desde']): ?><span class="time"><?=formatarTempoDecorrido($p['espera_desde'])?></span><br><small><?=date('d/m/Y H:i',strtotime($p['espera_desde']))?></small><?php else: ?>-<?php endif; ?></td><td><?= $p['ultima_resposta_paciente'] ? date('d/m/Y H:i',strtotime($p['ultima_resposta_paciente'])) : '-' ?></td><td><a href="paciente_perfil.php?id=<?=$p['paciente_id']?>" class="btn btn-primary btn-sm">Abrir</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></body></html>
